{
  "platform": "host",
  "provider": "Service",
  "method": "listService",
  "data": {
    "mode": "service",
    "service": {
      "key": "tools",
      "description": "Tool registry and execution pipeline. Scoped registrations shadow globals; one visibility resolver feeds presentation, lookup, and dispatch.",
      "access": {
        "optional": {
          "expression": "ctx.get(\"tools\")",
          "requiresUndefinedCheck": true
        },
        "hardDependency": {
          "inject": [
            "tools"
          ],
          "expression": "ctx.tools"
        }
      },
      "methods": [
        {
          "signature": "presentAs(mode: ToolPresentationMode): () => void",
          "description": "Present the calling scope's tools in `mode` instead of the deployment default. Nearest scope on the chain wins, so a preset's standing declaration covers every agent joined under it.\n\nScoped only, and one declaration per scope: this is how an agent preset composes PTC mode agents beside native ones in the same process, and a process-global override would be the `mode` config field instead.",
          "parameters": [
            {
              "name": "mode",
              "description": "the presentation the covered agents' models see."
            }
          ],
          "returns": "the exact disposer that restores the deployment default."
        },
        {
          "signature": "register(definition: ToolDefinition): () => void",
          "description": "Register globally or in the calling agent scope. Scoped tools shadow globals; duplicates within one layer and the reserved `run_code` name fail.",
          "parameters": [
            {
              "name": "definition",
              "description": "tool schema, execution, and optional finalization/presentation callbacks."
            }
          ],
          "returns": "the exact disposer that unregisters the tool."
        },
        {
          "signature": "replace(definition: ToolDefinition): () => void",
          "description": "Epic P1-09 must[2]: hand an already-owned tool name to a new owner through the EXPLICIT replace entry point, gated by ToolOwnershipConfig.allowReplace. A plain register of an owned name is never an override — it stays a `'capability-collision'` refusal even when policy permits replacement.",
          "parameters": [
            {
              "name": "definition",
              "description": "the replacing tool's schema, execution, and presentation callbacks."
            }
          ],
          "returns": "the exact disposer that unregisters the replacing tool."
        },
        {
          "signature": "declareOwner(identity: string): () => void",
          "description": "Epic P1-09 must[0]: bind the calling fiber's subtree to an explicit plugin identity, for a registrant whose stable identity no Loader entry carries. A dynamically defined Cordis package is the case this exists for: every one of them hangs under a single shared group fiber, so without an explicit declaration they would all resolve to one owner and no collision between two of them could ever be detected.",
          "parameters": [
            {
              "name": "identity",
              "description": "the stable identity to attribute this subtree's registrations to."
            }
          ],
          "returns": "the disposer that unbinds it, held by the calling fiber."
        },
        {
          "signature": "ownershipOf(name: string): CapabilityRegistration | undefined",
          "description": "Epic P1-09 must[0]: the ownership record the registry admitted for `name`.",
          "parameters": [
            {
              "name": "name",
              "description": "a global tool name."
            }
          ],
          "returns": "the live registration, or `undefined` when no plugin owns `name`."
        },
        {
          "signature": "ownershipHistory(): readonly CapabilityRegistration[]",
          "description": "Epic P1-09 acceptance[1]: every ownership record this registry currently holds, oldest first, including the superseded owners a legitimate replacement left behind. An unloaded plugin's records are absent — the gate's \"effects after unload = 0\" covers this history too.",
          "parameters": [],
          "returns": "the live ownership history in admission order."
        },
        {
          "signature": "revokeOwned(token: OwnershipToken): RevocationResult",
          "description": "Epic P1-09 must[3]: unregister exactly the tools whose stored ownership token equals `token`, and no others. Takes only a token — never a name or a plugin identity a caller could substitute — so cross-plugin revocation has no API surface to attempt through.",
          "parameters": [
            {
              "name": "token",
              "description": "the ownership token presented at unload time."
            }
          ],
          "returns": "which capability ids were revoked, or why nothing was."
        },
        {
          "signature": "restrict(filter: ToolRestriction): () => void",
          "description": "Restrict global tools for the calling agent scope. Empty filters, unknown names, scope-local names, and reserved transport names fail. Restrictions intersect; scoped registrations remain visible.",
          "parameters": [
            {
              "name": "filter",
              "description": "global-tool mask: `allow` (keep only) and/or `deny` (remove)."
            }
          ],
          "returns": "the exact disposer that lifts this restriction."
        },
        {
          "signature": "guard(guard: ToolGuard): () => void",
          "description": "Register a monotonic guard after the extensible `tools/pre-execute` waterfall. A plain-context guard applies globally; one registered through `agent.ctx` applies only to that agent. Any matching guard may deny by returning a reason, while no guard can force-allow a call another guard denied. The exact effect disposer is returned for ordered ownership and HMR cleanup.",
          "parameters": [
            {
              "name": "guard",
              "description": "synchronous check; a returned string denies the execution."
            }
          ],
          "returns": "the exact disposer that unregisters the guard."
        },
        {
          "signature": "requireCapabilityToken(): () => void",
          "description": "Epic P2-02 must[3]: require every tool call in this context's scope to present a Capability Token authorizing that tool. A plain-context registration arms the requirement for every call the registry receives; one registered through `agent.ctx` arms it for that agent's calls only.\n\nThe gate runs inside ToolRuntime.execute's own preparation, BEFORE the `tools/pre-execute` waterfall and the guard stage — the same placement as the `ptc` collapse and for the same reason: a call that cannot be authorized must never be observed, let alone approved, by extensible policy. Because preparation is the single funnel both `execute` and the agent loop's staged scheduler pass through, and because a transport sub-dispatch (a `parent` token set) funnels through it too, there is no alternate caller that reaches a tool body around this check.",
          "parameters": [],
          "returns": "the exact disposer that lifts this registration's requirement."
        },
        {
          "signature": "get(name: string, scope?: ScopeKey): ToolDefinition | undefined",
          "description": "Look up a tool as one scope sees it (scoped shadows global; a restricted-away global reads as absent). Presenters pass the calling agent so the rendered card matches the definition that actually executed.",
          "parameters": [
            {
              "name": "name",
              "description": "the tool name as registered."
            },
            {
              "name": "scope",
              "description": "the viewing scope (the agent); omitted = the global view."
            }
          ],
          "returns": "the definition the scope resolves, or undefined when none is visible."
        },
        {
          "signature": "schemas(scope?: ScopeKey): ToolSchema[]",
          "description": "Project visible definitions onto the allowlisted model-facing schema fields, excluding execution and presentation callbacks.",
          "parameters": [
            {
              "name": "scope",
              "description": "the viewing scope (the agent); omitted = the global view."
            }
          ],
          "returns": "one deep-cloned schema per visible tool."
        },
        {
          "signature": "executionMode(exec: ToolExecutionInput): ToolExecutionMode",
          "description": "Classify a pending call through the caller's visible tool definition. Only an exact `true` is parallel; unknown, hidden, undeclared, invalid, or throwing classifiers are exclusive.",
          "parameters": [
            {
              "name": "exec",
              "description": "call name, parsed arguments, and optional agent scope."
            }
          ],
          "returns": "the fail-closed scheduling mode."
        },
        {
          "signature": "async execute(exec: ToolExecutionInput): Promise<ToolExecutionResult>",
          "description": "Execute through pre-policy, guards, around-dispatch, post-policy, definition-owned content finalization, and final notification. Tool and listener failures resolve as materialized error results; an invisible tool reports `UNKNOWN_TOOL`. The returned outcome is the same lossless, frozen snapshot final observers receive. Cancellation arriving after entry and before final result materialization skips a not-yet-started body with `ABORTED_BEFORE_DISPATCH` or replaces a successful started outcome with `ABORTED`; already-started work is still drained and may retain a tool-owned structured error.",
          "parameters": [
            {
              "name": "exec",
              "description": "the typed same-process call input. The registry assigns its correlation token before policy begins."
            }
          ],
          "returns": "the materialized final result."
        }
      ]
    },
    "referencedTypes": [
